// Задание 3: Управление высоковольтной нагрузкой
const int relayPin = 12; 
const unsigned long ON_TIME = 32000; // 32 секунды
const unsigned long OFF_TIME = 25000; // 25 секунд

void setup() {
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
}

void loop() {
  // Включение нагрузки
  digitalWrite(relayPin, HIGH);
  delay(ON_TIME);

  // Выключение нагрузки
  digitalWrite(relayPin, LOW);
  delay(OFF_TIME);
}
